import sys

def hanoi(n, src, dst, aux, moves):
    if n == 0:
        return
    hanoi(n-1, src, aux, dst, moves)
    moves.append((src, dst))
    hanoi(n-1, aux, dst, src, moves)


def main():
    n = int(sys.stdin.readline())
    moves = []
    hanoi(n, 'A', 'C', 'B', moves)
    for a, b in moves:
        print(a, b)

if __name__ == "__main__":
    main()

