#include <iostream>
#include <utility>
#include <vector>
using namespace std;

void hanoi(int n, char src, char dst, char aux, vector<pair<char,char>>& moves) {
    if (n == 0) return;
    hanoi(n-1, src, aux, dst, moves);
    moves.emplace_back(src, dst);
    hanoi(n-1, aux, dst, src, moves);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; if(!(cin>>n)) return 0;
    vector<pair<char,char>> moves;
    hanoi(n, 'A', 'C', 'B', moves);
    for (auto &p : moves) {
        cout << p.first << ' ' << p.second << '\n';
    }
    return 0;
}
